mapper.update:
UPDATE inventory_sync_run
   SET heartbeat_at = SYSTIMESTAMP, lease_expires_at = #{leaseExpiresAt},
       lease_owner_instance_id = #{owner}, updated_at = SYSTIMESTAMP
 WHERE inventory_sync_run_id = #{runId} AND main_attempt_no = #{attemptNo}
   AND fencing_token = #{fencingToken} AND lease_owner_instance_id = #{owner}
   AND run_status = 'RUNNING'

mapper.select:
SELECT COUNT(*) FROM inventory_sync_run
 WHERE inventory_sync_run_id = #{runId} AND main_attempt_no = #{attemptNo}
   AND fencing_token = #{fencingToken} AND run_status = 'RUNNING'

mapper.insert:
INSERT INTO inventory_sync_error (
    inventory_sync_run_id, source_type, error_phase, error_code, error_message
) VALUES (#{runId}, #{sourceType}, #{phase}, #{errorCode}, #{errorMessage})
